import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { useNavigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './components/AuthProvider';
import Register from './components/Register';
import Login from './components/Login';
import Search from './components/Search';

const App = () => {
  const navigate = useNavigate();
  const { auth } = useAuth(); // Assuming this provides authentication state

  return (
    <div>
      <nav>
        <ul>
          <li><a href="/">Register</a></li>
          <li><a href="/login">Login</a></li>
          <li><a href="/search">Search</a></li>
        </ul>
      </nav>
      <Routes>
        <Route path="/" element={auth?.isLoggedIn ? <Navigate to="/search" /> : <Register />} />
        <Route path="/login" element={auth?.isLoggedIn ? <Navigate to="/search" /> : <Login />} />
        <Route path="/search" element={auth?.isLoggedIn ? <Search /> : <Navigate to="/login" />} />
      </Routes>
    </div>
  );
};

const AppWrapper = () => (
  <Router>
    <AuthProvider>
      <App />
    </AuthProvider>
  </Router>
);

export default AppWrapper;
